/* C code example */
#include <unistd.h>
int main() {
  int rc = fork();
  if (rc < 0) { /* fork failed */
    fprintf(stderr, "fork failed\n");
    exit(1);
  }
  else if (rc == 0) { /* child process (new process) */
    // Child process code
  }
  else { /* parent process */
    // Parent process code
  }
  return 0;
}
